from collections import OrderedDict


class LRUCache:
    """A fixed-capacity cache that evicts the least recently used entry."""

    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self.capacity = capacity
        self._data = OrderedDict()

    def get(self, key, default=None):
        """Return the value for key, marking it as most recently used."""
        if key not in self._data:
            return default
        self._data.move_to_end(key)
        return self._data[key]

    def put(self, key, value):
        """Insert or update key, evicting the oldest entry if over capacity."""
        if key in self._data:
            self._data.move_to_end(key)
        self._data[key] = value
        if len(self._data) > self.capacity:
            self._data.popitem(last=False)

    def __contains__(self, key):
        return key in self._data

    def __len__(self):
        return len(self._data)

    def __repr__(self):
        return f"LRUCache(capacity={self.capacity}, size={len(self._data)})"


if __name__ == "__main__":
    cache = LRUCache(2)
    cache.put("a", 1)
    cache.put("b", 2)
    cache.get("a")          # "a" is now the most recent
    cache.put("c", 3)       # evicts "b"
    print(cache.get("a"))   # 1
    print(cache.get("b"))   # None
    print(cache.get("c"))   # 3
```

`get` accepts a `default` so a stored `None` is distinguishable from a miss only if you pass a sentinel — swap the default for one if that matters in your use.

